/* TrafficLight: switch-based hierarchical state machine generated by MachinaState (C99). Do not edit by hand. */
#include "TrafficLight.h"

/* Internal functions */
static size_t RegionOf(Demo_TrafficLight_State state);
static size_t FirstRegionOf(Demo_TrafficLight_State state);
static size_t RegionsOf(Demo_TrafficLight_State state);
static void Trace(Demo_TrafficLight* m, Demo_TrafficLight_TraceKind kind, const char* name);
static void OnEntry(Demo_TrafficLight* m, Demo_TrafficLight_State state);
static void OnExit(Demo_TrafficLight* m, Demo_TrafficLight_State state);
static Demo_TrafficLight_State Innermost(const Demo_TrafficLight* m, Demo_TrafficLight_State state);
static void ExitState(Demo_TrafficLight* m, Demo_TrafficLight_State state);
static void EnterState(Demo_TrafficLight* m, Demo_TrafficLight_State state);
static void EnterRegion(Demo_TrafficLight* m, size_t region);
static void EnterDefault(Demo_TrafficLight* m, Demo_TrafficLight_State state);
static void EnterHistory(Demo_TrafficLight* m, Demo_TrafficLight_State state, bool deep);
static void EnterDown(Demo_TrafficLight* m, Demo_TrafficLight_State from, Demo_TrafficLight_State target, bool history);
static bool HandleEvent(Demo_TrafficLight* m, Demo_TrafficLight_State state, Demo_TrafficLight_Event event);
static bool DispatchState(Demo_TrafficLight* m, Demo_TrafficLight_State state, Demo_TrafficLight_Event event);
static bool DispatchCore(Demo_TrafficLight* m, Demo_TrafficLight_Event event);

static size_t RegionOf(Demo_TrafficLight_State state) {
    switch (state) {
        case Demo_TrafficLight_State_Red:
        case Demo_TrafficLight_State_Green:
        case Demo_TrafficLight_State_Yellow:
            return 1;
        default:
            return 0;
    }
}

static size_t FirstRegionOf(Demo_TrafficLight_State state) {
    switch (state) {
        case Demo_TrafficLight_State_Operating:
            return 1;
        default:
            return 0;
    }
}

static size_t RegionsOf(Demo_TrafficLight_State state) {
    switch (state) {
        case Demo_TrafficLight_State_Operating:
            return 1;
        default:
            return 0;
    }
}

Demo_TrafficLight_State Demo_TrafficLight_ParentOf(Demo_TrafficLight_State state) {
    switch (state) {
        case Demo_TrafficLight_State_Red:
        case Demo_TrafficLight_State_Green:
        case Demo_TrafficLight_State_Yellow:
            return Demo_TrafficLight_State_Operating;
        default:
            return Demo_TrafficLight_State_None;
    }
}

const char* Demo_TrafficLight_StateName(Demo_TrafficLight_State state) {
    switch (state) {
        case Demo_TrafficLight_State_Off:
            return "Off";
        case Demo_TrafficLight_State_Operating:
            return "Operating";
        case Demo_TrafficLight_State_Red:
            return "Red";
        case Demo_TrafficLight_State_Green:
            return "Green";
        case Demo_TrafficLight_State_Yellow:
            return "Yellow";
        case Demo_TrafficLight_State_Flashing:
            return "Flashing";
        default:
            return "None";
    }
}

const char* Demo_TrafficLight_EventName(Demo_TrafficLight_Event event) {
    switch (event) {
        case Demo_TrafficLight_Event_Timer:
            return "Timer";
        case Demo_TrafficLight_Event_PedestrianRequest:
            return "PedestrianRequest";
        case Demo_TrafficLight_Event_PowerOn:
            return "PowerOn";
        case Demo_TrafficLight_Event_PowerOff:
            return "PowerOff";
        case Demo_TrafficLight_Event_Fault:
            return "Fault";
        case Demo_TrafficLight_Event_Repair:
            return "Repair";
        default:
            return "";
    }
}

static void Trace(Demo_TrafficLight* m, Demo_TrafficLight_TraceKind kind, const char* name) {
    if (m->hooks->Trace != NULL) {
        m->hooks->Trace(m->context, kind, name);
    }
}

static void OnEntry(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    switch (state) {
        case Demo_TrafficLight_State_Red:
            m->hooks->redOn(m->context);
            break;
        case Demo_TrafficLight_State_Green:
            m->hooks->greenOn(m->context);
            break;
        case Demo_TrafficLight_State_Yellow:
            m->hooks->yellowOn(m->context);
            break;
        case Demo_TrafficLight_State_Flashing:
            m->hooks->flashOn(m->context);
            break;
        default:
            break;
    }
}

static void OnExit(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    switch (state) {
        case Demo_TrafficLight_State_Red:
            m->hooks->redOff(m->context);
            break;
        case Demo_TrafficLight_State_Green:
            m->hooks->greenOff(m->context);
            break;
        case Demo_TrafficLight_State_Yellow:
            m->hooks->yellowOff(m->context);
            break;
        case Demo_TrafficLight_State_Flashing:
            m->hooks->flashOff(m->context);
            break;
        default:
            break;
    }
}

static Demo_TrafficLight_State Innermost(const Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    while (state != Demo_TrafficLight_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Demo_TrafficLight_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static void ExitState(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Demo_TrafficLight_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    Trace(m, Demo_TrafficLight_Trace_Exit, Demo_TrafficLight_StateName(state));
    OnExit(m, state);
    m->active[RegionOf(state)] = Demo_TrafficLight_State_None;
    m->history[RegionOf(state)] = state;
}

static void EnterState(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    m->active[RegionOf(state)] = state;
    Trace(m, Demo_TrafficLight_Trace_Enter, Demo_TrafficLight_StateName(state));
    OnEntry(m, state);
}

static void EnterRegion(Demo_TrafficLight* m, size_t region) {
    switch (region) {
        case 1:
            EnterDown(m, Demo_TrafficLight_State_Operating, Demo_TrafficLight_State_Red, false);
            break;
        default:
            break;
    }
}

static void EnterDefault(Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
}

static void EnterHistory(Demo_TrafficLight* m, Demo_TrafficLight_State state, bool deep) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        const Demo_TrafficLight_State remembered = m->history[region];
        if (remembered == Demo_TrafficLight_State_None) {
            EnterRegion(m, region);
        } else if (deep) {
            EnterState(m, remembered);
            EnterHistory(m, remembered, true);
        } else {
            EnterDown(m, state, remembered, false);
        }
    }
}

static void EnterDown(Demo_TrafficLight* m, Demo_TrafficLight_State from, Demo_TrafficLight_State target, bool history) {
    Demo_TrafficLight_State state = target;
    Demo_TrafficLight_State next = Demo_TrafficLight_State_None;
    while (Demo_TrafficLight_ParentOf(state) != from) {
        next = state;
        state = Demo_TrafficLight_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Demo_TrafficLight_State_None) {
        if (history) {
            EnterHistory(m, state, false);
            return;
        }
        EnterDefault(m, state);
        return;
    }
    EnterDown(m, state, target, history);
}

static bool HandleEvent(Demo_TrafficLight* m, Demo_TrafficLight_State state, Demo_TrafficLight_Event event) {
    switch (state) {
        case Demo_TrafficLight_State_Off:
            switch (event) {
                case Demo_TrafficLight_Event_PowerOn:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Off -> Operating");
                    ExitState(m, Demo_TrafficLight_State_Off);
                    EnterDown(m, Demo_TrafficLight_State_None, Demo_TrafficLight_State_Operating, false);
                    return true;
                default:
                    break;
            }
            break;
        case Demo_TrafficLight_State_Operating:
            switch (event) {
                case Demo_TrafficLight_Event_PowerOff:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Operating -> Off");
                    ExitState(m, Demo_TrafficLight_State_Operating);
                    EnterDown(m, Demo_TrafficLight_State_None, Demo_TrafficLight_State_Off, false);
                    return true;
                case Demo_TrafficLight_Event_Fault:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Operating -> Flashing");
                    ExitState(m, Demo_TrafficLight_State_Operating);
                    m->hooks->logFault(m->context);
                    EnterDown(m, Demo_TrafficLight_State_None, Demo_TrafficLight_State_Flashing, false);
                    return true;
                default:
                    break;
            }
            break;
        case Demo_TrafficLight_State_Red:
            switch (event) {
                case Demo_TrafficLight_Event_Timer:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Red -> Green");
                    ExitState(m, Demo_TrafficLight_State_Red);
                    EnterDown(m, Demo_TrafficLight_State_Operating, Demo_TrafficLight_State_Green, false);
                    return true;
                default:
                    break;
            }
            break;
        case Demo_TrafficLight_State_Green:
            switch (event) {
                case Demo_TrafficLight_Event_Timer:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Green -> Yellow");
                    ExitState(m, Demo_TrafficLight_State_Green);
                    EnterDown(m, Demo_TrafficLight_State_Operating, Demo_TrafficLight_State_Yellow, false);
                    return true;
                case Demo_TrafficLight_Event_PedestrianRequest:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Green (internal)");
                    m->hooks->shortenGreen(m->context);
                    return true;
                default:
                    break;
            }
            break;
        case Demo_TrafficLight_State_Yellow:
            switch (event) {
                case Demo_TrafficLight_Event_Timer:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Yellow -> Red");
                    ExitState(m, Demo_TrafficLight_State_Yellow);
                    EnterDown(m, Demo_TrafficLight_State_Operating, Demo_TrafficLight_State_Red, false);
                    return true;
                default:
                    break;
            }
            break;
        case Demo_TrafficLight_State_Flashing:
            switch (event) {
                case Demo_TrafficLight_Event_PowerOff:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Flashing -> Off");
                    ExitState(m, Demo_TrafficLight_State_Flashing);
                    EnterDown(m, Demo_TrafficLight_State_None, Demo_TrafficLight_State_Off, false);
                    return true;
                case Demo_TrafficLight_Event_Repair:
                    Trace(m, Demo_TrafficLight_Trace_Transition, "Flashing -> Operating (history)");
                    ExitState(m, Demo_TrafficLight_State_Flashing);
                    EnterDown(m, Demo_TrafficLight_State_None, Demo_TrafficLight_State_Operating, true);
                    return true;
                default:
                    break;
            }
            break;
        default:
            break;
    }
    return false;
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Demo_TrafficLight* m, Demo_TrafficLight_State state, Demo_TrafficLight_Event event) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Demo_TrafficLight_State_None && DispatchState(m, m->active[region], event)) {
            return true;
        }
    }
    return HandleEvent(m, state, event);
}

static bool DispatchCore(Demo_TrafficLight* m, Demo_TrafficLight_Event event) {
    Trace(m, Demo_TrafficLight_Trace_Event, Demo_TrafficLight_EventName(event));
    if (m->active[0] != Demo_TrafficLight_State_None && DispatchState(m, m->active[0], event)) {
        return true;
    }
    Trace(m, Demo_TrafficLight_Trace_Ignored, Demo_TrafficLight_EventName(event));
    return false;
}

void Demo_TrafficLight_Init(Demo_TrafficLight* m, const Demo_TrafficLight_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Demo_TrafficLight_RegionCount; ++i) {
        m->active[i] = Demo_TrafficLight_State_None;
        m->history[i] = Demo_TrafficLight_State_None;
    }
}

void Demo_TrafficLight_Start(Demo_TrafficLight* m) {
    size_t i;
    for (i = 0; i < Demo_TrafficLight_RegionCount; ++i) {
        m->active[i] = Demo_TrafficLight_State_None;
        m->history[i] = Demo_TrafficLight_State_None;
    }
    Trace(m, Demo_TrafficLight_Trace_Start, "TrafficLight");
    EnterDown(m, Demo_TrafficLight_State_None, Demo_TrafficLight_State_Off, false);
}

bool Demo_TrafficLight_Dispatch(Demo_TrafficLight* m, Demo_TrafficLight_Event event) {
    bool handled = false;
    handled = DispatchCore(m, event);
    return handled;
}

Demo_TrafficLight_State Demo_TrafficLight_Current(const Demo_TrafficLight* m) {
    return Innermost(m, m->active[0]);
}

bool Demo_TrafficLight_IsIn(const Demo_TrafficLight* m, Demo_TrafficLight_State state) {
    return state != Demo_TrafficLight_State_None && m->active[RegionOf(state)] == state;
}

bool Demo_TrafficLight_IsFinished(const Demo_TrafficLight* m) {
    return ((void)m, false);
}

